package com.aoo.bcg.wordcard;import java.util.*;/**桂林字牌，移植 GLZPHuXiEnum/HuTypeEnum。*/public final class GlzpRules{public record Config(int playerCount,int drawRemoval,int charge,boolean selfDrawMandatory,boolean oppositeCannotChi,boolean guChou,boolean scoreFloorZero){public Config{if(playerCount<2||playerCount>3||!Set.of(0,10,15,20).contains(drawRemoval))throw new IllegalArgumentException("invalid GLZP room");}}public enum HuType{NONE,RED,EIGHTEEN_BIG,SIXTEEN_SMALL}private GlzpRules(){}public static List<Integer>deck(){List<Integer>x=new ArrayList<>(80);for(int t=10;t<=29;t++)for(int c=1;c<=4;c++)x.add(t*100+c);return List.copyOf(x);}public static int type(int c){return c/100;}public static boolean big(int c){return type(c)>=20;}public static int meldHuXi(WordCardOperation op,int c){boolean b=big(c);return switch(op){case PENG->b?3:1;case WEI->b?6:3;case PAO->b?9:6;case TI->b?12:9;default->0;};}public static boolean legalChi(Collection<Integer>h,int e,Set<Integer>passed,boolean noOpp,boolean opp){if(noOpp&&opp||passed.contains(type(e)))return false;List<Integer>t=h.stream().map(GlzpRules::type).toList();int n=type(e);return t.contains(n-1)&&t.contains(n+1)||t.contains(n+1)&&t.contains(n+2)||Set.of(2,7,10).contains(n%10)&&Set.of(2,7,10).stream().filter(r->r!=n%10).allMatch(r->t.contains(n/10*10+r));}public static boolean canHu(Collection<Integer>c,int xi){return xi>=15&&c.size()%3==2;}public static HuType colorWin(Collection<Integer>c){long red=c.stream().filter(x->Set.of(2,7,10).contains(type(x)%10)).count(),big=c.stream().filter(GlzpRules::big).count(),small=c.size()-big;if(red>=10)return HuType.RED;if(big>=18)return HuType.EIGHTEEN_BIG;if(small>=16)return HuType.SIXTEEN_SMALL;return HuType.NONE;}public static long winnerScore(int xi,HuType t,int charge,int wp,int lp){long tun=Math.max(1,(xi-12)/3);if(t!=HuType.NONE)tun*=2;return tun+charge+wp+lp;}}
